import{_ as e,z as a,m as n,ap as t}from"./chunks/framework.40Eg4YuW.js";const g=JSON.parse('{"title":"配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"markdown/config.md","filePath":"markdown/config.md","lastUpdated":1785843060000}'),s={name:"markdown/config.md"};function r(i,o,l,d,p,h){return n(),a("div",null,o[0]||(o[0]=[t(`<h1 id="配置指南" tabindex="-1">配置指南 <a class="header-anchor" href="#配置指南" aria-label="Permalink to &quot;配置指南&quot;">​</a></h1><h2 id="基础设置" tabindex="-1">基础设置 <a class="header-anchor" href="#基础设置" aria-label="Permalink to &quot;基础设置&quot;">​</a></h2><h3 id="selfid" tabindex="-1">selfId <a class="header-anchor" href="#selfid" aria-label="Permalink to &quot;selfId&quot;">​</a></h3><p><strong>类型</strong>: <code>string</code>（必需）</p><p><strong>格式</strong>: 纯数字 UID</p><p><strong>描述</strong>: 要登录的 Bilibili 账号 UID。扫码登录成功后，Cookie 中的账号 UID 必须与此配置一致。</p><p>如果账号不一致，适配器会保留插件运行状态，并在前端显示“扫码账号和配置项账号不一致，请更换账号”，同时在 Koishi 日志中记录原因。</p><p>如何查找 UID？<a href="./../markdown/quick-start.html">点我查看方法</a></p><h2 id="进阶设置" tabindex="-1">进阶设置 <a class="header-anchor" href="#进阶设置" aria-label="Permalink to &quot;进阶设置&quot;">​</a></h2><h3 id="pollinterval" tabindex="-1">pollInterval <a class="header-anchor" href="#pollinterval" aria-label="Permalink to &quot;pollInterval&quot;">​</a></h3><p><strong>类型</strong>: <code>number</code></p><p><strong>默认值</strong>: <code>3000</code></p><p><strong>范围</strong>: <code>1000</code> - <code>60000</code></p><p><strong>单位</strong>: 毫秒</p><p><strong>描述</strong>: 私信轮询间隔。数值越小，私信响应越快，但 API 请求会更频繁。</p><h3 id="maxcachesize" tabindex="-1">maxCacheSize <a class="header-anchor" href="#maxcachesize" aria-label="Permalink to &quot;maxCacheSize&quot;">​</a></h3><p><strong>类型</strong>: <code>number</code></p><p><strong>默认值</strong>: <code>1000</code></p><p><strong>范围</strong>: <code>100</code> - <code>10000</code></p><p><strong>单位</strong>: 条</p><p><strong>描述</strong>: 缓存已处理的消息 ID 数量，用于避免轮询造成重复处理。</p><h3 id="ignoreofflinemessages" tabindex="-1">ignoreOfflineMessages <a class="header-anchor" href="#ignoreofflinemessages" aria-label="Permalink to &quot;ignoreOfflineMessages&quot;">​</a></h3><p><strong>类型</strong>: <code>boolean</code></p><p><strong>默认值</strong>: <code>true</code></p><p><strong>描述</strong>: 开启后，只响应机器人上线之后产生的未读私信；关闭后可能会处理机器人离线期间积累的历史未读消息。</p><h3 id="requesttimeout" tabindex="-1">requestTimeout <a class="header-anchor" href="#requesttimeout" aria-label="Permalink to &quot;requestTimeout&quot;">​</a></h3><p><strong>类型</strong>: <code>number</code></p><p><strong>默认值</strong>: <code>10000</code></p><p><strong>范围</strong>: <code>3000</code> - <code>30000</code></p><p><strong>单位</strong>: 毫秒</p><p><strong>描述</strong>: 请求 Bilibili API 的超时时间。</p><h2 id="监听设置" tabindex="-1">监听设置 <a class="header-anchor" href="#监听设置" aria-label="Permalink to &quot;监听设置&quot;">​</a></h2><h3 id="enablecommentpolling" tabindex="-1">enableCommentPolling <a class="header-anchor" href="#enablecommentpolling" aria-label="Permalink to &quot;enableCommentPolling&quot;">​</a></h3><p><strong>类型</strong>: <code>boolean</code></p><p><strong>默认值</strong>: <code>true</code></p><p><strong>描述</strong>: 是否轮询 Bilibili 的评论通知。启用后，视频评论区和图文动态评论区中提及机器人或回复相关评论的消息会作为 Koishi Session 下发。</p><h3 id="commentpollinterval" tabindex="-1">commentPollInterval <a class="header-anchor" href="#commentpollinterval" aria-label="Permalink to &quot;commentPollInterval&quot;">​</a></h3><p><strong>类型</strong>: <code>number</code></p><p><strong>默认值</strong>: <code>30</code></p><p><strong>范围</strong>: <code>10</code> - <code>300</code></p><p><strong>单位</strong>: 秒</p><p><strong>描述</strong>: 评论通知轮询间隔。</p><p>评论频道使用以下命名规则：</p><ul><li>视频评论区：<code>video:BV号</code></li><li>图文动态评论区：<code>opus:动态ID</code></li></ul><p>机器人发送评论时会回复触发通知的目标评论，而不是发送帖子下的一级评论。评论内容中的 @ 会解析成 Koishi <code>at</code> 元素，并保留被 @ 用户的 UID。</p><h3 id="enabledynamicpolling" tabindex="-1">enableDynamicPolling <a class="header-anchor" href="#enabledynamicpolling" aria-label="Permalink to &quot;enableDynamicPolling&quot;">​</a></h3><p><strong>类型</strong>: <code>boolean</code></p><p><strong>默认值</strong>: <code>true</code></p><p><strong>描述</strong>: 是否监听关注 UP 主的动态更新。该功能是动态事件监听，不等同于评论通知监听。</p><h3 id="dynamicpollinterval" tabindex="-1">dynamicPollInterval <a class="header-anchor" href="#dynamicpollinterval" aria-label="Permalink to &quot;dynamicPollInterval&quot;">​</a></h3><p><strong>类型</strong>: <code>number</code></p><p><strong>默认值</strong>: <code>30</code></p><p><strong>范围</strong>: <code>10</code> - <code>300</code></p><p><strong>单位</strong>: 秒</p><p><strong>描述</strong>: 动态事件轮询间隔。</p><h3 id="enablelivepolling" tabindex="-1">enableLivePolling <a class="header-anchor" href="#enablelivepolling" aria-label="Permalink to &quot;enableLivePolling&quot;">​</a></h3><p><strong>类型</strong>: <code>boolean</code></p><p><strong>默认值</strong>: <code>true</code></p><p><strong>描述</strong>: 是否监听关注 UP 主的直播状态变化。</p><h3 id="livepollinterval" tabindex="-1">livePollInterval <a class="header-anchor" href="#livepollinterval" aria-label="Permalink to &quot;livePollInterval&quot;">​</a></h3><p><strong>类型</strong>: <code>number</code></p><p><strong>默认值</strong>: <code>30</code></p><p><strong>范围</strong>: <code>10</code> - <code>300</code></p><p><strong>单位</strong>: 秒</p><p><strong>描述</strong>: 直播状态轮询间隔。</p><h2 id="屏蔽设置" tabindex="-1">屏蔽设置 <a class="header-anchor" href="#屏蔽设置" aria-label="Permalink to &quot;屏蔽设置&quot;">​</a></h2><h3 id="nestedblocked-blockeduids" tabindex="-1">nestedblocked.blockedUids <a class="header-anchor" href="#nestedblocked-blockeduids" aria-label="Permalink to &quot;nestedblocked.blockedUids&quot;">​</a></h3><p><strong>类型</strong>: <code>Array&lt;{ name: string; uid: string }&gt;</code></p><p><strong>默认值</strong>: 预设的 Bilibili 官方账号列表</p><p><strong>描述</strong>: 不响应其私信的用户 UID 列表。表格中的 <code>name</code> 仅用于标识，实际匹配使用 <code>uid</code>。</p><p><code>uid</code> 支持使用 <code>*</code> 匹配所有用户。示例：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">[</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">  { </span><span style="--shiki-light:#005CC5;--shiki-dark:#E06C75;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;">&quot;测试用户&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#E06C75;">&quot;uid&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;">&quot;123456789&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">  { </span><span style="--shiki-light:#005CC5;--shiki-dark:#E06C75;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;">&quot;全部用户&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#E06C75;">&quot;uid&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;">&quot;*&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">]</span></span></code></pre></div><h2 id="轮询容错" tabindex="-1">轮询容错 <a class="header-anchor" href="#轮询容错" aria-label="Permalink to &quot;轮询容错&quot;">​</a></h2><h3 id="pollfailurethreshold" tabindex="-1">pollFailureThreshold <a class="header-anchor" href="#pollfailurethreshold" aria-label="Permalink to &quot;pollFailureThreshold&quot;">​</a></h3><p><strong>类型</strong>: <code>number</code></p><p><strong>默认值</strong>: <code>10</code></p><p><strong>范围</strong>: <code>1</code> - <code>29</code></p><p><strong>描述</strong>: 连续轮询失败达到此次数后，适配器会增加轮询间隔。</p><h3 id="pollautoshutdownthreshold" tabindex="-1">pollAutoShutdownThreshold <a class="header-anchor" href="#pollautoshutdownthreshold" aria-label="Permalink to &quot;pollAutoShutdownThreshold&quot;">​</a></h3><p><strong>类型</strong>: <code>number</code></p><p><strong>默认值</strong>: <code>30</code></p><p><strong>范围</strong>: <code>30</code> - <code>100</code></p><p><strong>描述</strong>: 连续轮询失败达到此次数后，适配器会自动关闭，避免在 Cookie 失效或网络异常时持续请求。</p><h2 id="开发调试选项" tabindex="-1">开发调试选项 <a class="header-anchor" href="#开发调试选项" aria-label="Permalink to &quot;开发调试选项&quot;">​</a></h2><h3 id="loggerinfo" tabindex="-1">loggerinfo <a class="header-anchor" href="#loggerinfo" aria-label="Permalink to &quot;loggerinfo&quot;">​</a></h3><p><strong>类型</strong>: <code>boolean</code></p><p><strong>默认值</strong>: <code>false</code></p><p><strong>标记</strong>: 实验性功能</p><p><strong>描述</strong>: 输出私信、登录、评论等功能的详细调试日志，用于定位问题。</p><h3 id="loggerliveinfo" tabindex="-1">loggerLiveInfo <a class="header-anchor" href="#loggerliveinfo" aria-label="Permalink to &quot;loggerLiveInfo&quot;">​</a></h3><p><strong>类型</strong>: <code>boolean</code></p><p><strong>默认值</strong>: <code>false</code></p><p><strong>标记</strong>: 实验性功能</p><p><strong>描述</strong>: 输出直播间弹幕的详细调试日志，可能产生大量日志，仅建议开发者临时开启。</p><h2 id="头像处理" tabindex="-1">头像处理 <a class="header-anchor" href="#头像处理" aria-label="Permalink to &quot;头像处理&quot;">​</a></h2><p>ilibili 图片通常要求特定请求头，机器人头像会通过 Koishi 本地服务反代后再提供给控制台；普通用户头像仍使用 Bilibili 原始链接。</p>`,96)]))}const u=e(s,[["render",r]]);export{g as __pageData,u as default};
